script:
var dateInput = root_element.querySelector('#scp-date-input');
var refreshBtn = root_element.querySelector('#scp-refresh-btn');

// Tab switching - scoped to root_element like harvest dashboard
root_element.querySelectorAll('.scp-tab-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
        var tab = this.dataset.tab;
        root_element.querySelectorAll('.scp-tab-btn').forEach(function(b) { b.classList.remove('active'); });
        root_element.querySelectorAll('.scp-tab-content').forEach(function(c) { c.classList.remove('active'); });
        this.classList.add('active');
        var el = root_element.querySelector('#scp-tab-' + tab);
        if (el) el.classList.add('active');
        // Render the weekly chart only once the Summary tab is visible — a
        // frappe.Chart built inside a display:none container gets zero width.
        if (tab === 'summary') scpLoadSummary();
    });
});

function scpOnDateChange() {
    scpLoad();
    var summaryTab = root_element.querySelector('#scp-tab-summary');
    if (summaryTab && summaryTab.classList.contains('active')) scpLoadSummary();
}

// Init date
if (dateInput) {
    dateInput.value = new Date().toISOString().slice(0, 10);
    dateInput.addEventListener('change', scpOnDateChange);
}
if (refreshBtn) refreshBtn.addEventListener('click', scpOnDateChange);

function scpLoad() {
    var today = dateInput ? dateInput.value : new Date().toISOString().slice(0, 10);
    var fmt = new Date(today + 'T00:00:00').toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'short', year: 'numeric' });
    var sub = root_element.querySelector('#scp-date-display');
    if (sub) sub.textContent = fmt;

    ['entries', 'scouts', 'beds', 'ghs'].forEach(function(k) {
        var el = root_element.querySelector('#scp-kpi-' + k);
        if (el) { el.textContent = '—'; el.closest('.scp-stat-card').classList.add('loading'); }
    });

    fetch('/api/method/upande_scp.serverscripts.get_workspace_stats.getWorkspaceStats', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-Frappe-CSRF-Token': frappe.csrf_token || '' },
        body: JSON.stringify({ date: today })
    }).then(function(r) { return r.json(); }).then(function(r) {
        var d = r.message || {};
        function set(id, val) {
            var el = root_element.querySelector('#scp-kpi-' + id);
            if (el) { el.textContent = val; el.closest('.scp-stat-card').classList.remove('loading'); }
        }
        set('entries', d.total_entries || 0);
        set('scouts',  d.scouts_active || 0);
        set('beds',    d.beds_scouted  || 0);
        set('ghs',     d.greenhouses_scouted || 0);
        var insights = root_element.querySelector('#scp-insights');
        if (insights) {
            var parts = [];
            if (d.top_pest)    parts.push('<div class="scp-insight-item"><span class="scp-insight-dot" style="background:#ef4444"></span><span class="scp-insight-label">Top Pest: </span><span class="scp-insight-value">' + d.top_pest + '</span></div>');
            if (d.top_disease) parts.push('<div class="scp-insight-item"><span class="scp-insight-dot" style="background:#f59e0b"></span><span class="scp-insight-label">Top Disease: </span><span class="scp-insight-value">' + d.top_disease + '</span></div>');
            insights.innerHTML = parts.join('') || '<span style="color:var(--text-muted);font-size:0.8rem">No observations recorded yet today.</span>';
        }
    }).catch(function() {
        ['entries', 'scouts', 'beds', 'ghs'].forEach(function(k) {
            var el = root_element.querySelector('#scp-kpi-' + k);
            if (el) { el.textContent = '?'; el.closest('.scp-stat-card').classList.remove('loading'); }
        });
    });
}

var scpChart = null;
function scpLoadSummary() {
    var date = dateInput ? dateInput.value : new Date().toISOString().slice(0, 10);
    var el = root_element.querySelector('#scp-weekly-chart');
    var empty = root_element.querySelector('#scp-chart-empty');
    fetch('/api/method/upande_scp.serverscripts.get_weekly_summary.getWeeklySummary', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-Frappe-CSRF-Token': frappe.csrf_token || '' },
        body: JSON.stringify({ date: date })
    }).then(function(r) { return r.json(); }).then(function(r) {
        var d = r.message || {};
        var series = (d.pests || []).concat(d.diseases || [], d.beds || []);
        var total = series.reduce(function(a, b) { return a + b; }, 0);
        if (!total) {
            if (el) el.innerHTML = '';
            if (empty) { empty.style.display = 'block'; empty.textContent = 'No scouting data in the last 7 days.'; }
            scpChart = null;
            return;
        }
        if (empty) empty.style.display = 'none';
        if (!el || !window.frappe || !frappe.Chart) return;
        el.innerHTML = '';
        scpChart = new frappe.Chart(el, {
            type: 'line',
            height: 280,
            colors: ['#ef4444', '#f59e0b', '#3b82f6'],
            axisOptions: { xIsSeries: 1 },
            lineOptions: { hideDots: 0, regionFill: 1, spline: 1 },
            data: {
                labels: d.labels || [],
                datasets: [
                    { name: 'Pests', values: d.pests || [] },
                    { name: 'Diseases', values: d.diseases || [] },
                    { name: 'Beds covered', values: d.beds || [] }
                ]
            }
        });
    }).catch(function() {
        if (el) el.innerHTML = '';
        if (empty) { empty.style.display = 'block'; empty.textContent = 'Could not load the weekly summary.'; }
    });
}

scpLoad();

style:
.scp-dash-v2 { font-family: var(--font-stack); padding: 0; }

.scp-tabs { display: inline-flex; gap: 4px; margin-bottom: 20px; background: var(--bg-color); border-radius: 999px; padding: 4px; border: 1px solid var(--border-color); width: fit-content; }
.scp-tab-btn { display: flex; align-items: center; gap: 8px; padding: 8px 22px; border: none; background: transparent; color: var(--text-muted); font-size: 0.875rem; font-weight: 500; cursor: pointer; border-radius: 999px; transition: background 0.2s, color 0.2s; }
.scp-tab-btn.active { background: var(--primary); color: white; box-shadow: 0 1px 3px rgba(0,0,0,.12); }
.scp-tab-content { display: none; }
.scp-tab-content.active { display: block; animation: scp-tab-in .28s cubic-bezier(.4, 0, .2, 1); }
@keyframes scp-tab-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

.scp-chart-card { background: var(--fg-color); border: 1px solid var(--border-color); border-radius: 12px; padding: 12px 8px 4px; min-height: 300px; position: relative; }
.scp-chart { width: 100%; }
.scp-chart-empty { display: none; text-align: center; color: var(--text-muted); font-size: 0.85rem; padding: 110px 0; }

.scp-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 20px; flex-wrap: wrap; gap: 12px; }
.scp-title { font-size: 1.25rem; font-weight: 600; color: var(--text-color); margin: 0 0 4px 0; }
.scp-subtitle { font-size: 0.8125rem; color: var(--text-muted); }
.scp-header-right { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }

.scp-filter-input { padding: 8px 12px; border: 1px solid var(--border-color); border-radius: 8px; font-size: 0.875rem; background: var(--fg-color); color: var(--text-color); }
.scp-filter-input:focus { outline: none; border-color: var(--primary); box-shadow: 0 0 0 3px rgba(44,123,229,0.1); }

.scp-refresh-btn { display: flex; align-items: center; padding: 8px 16px; background: var(--primary); color: white; border: none; border-radius: 8px; font-size: 0.875rem; font-weight: 500; cursor: pointer; transition: opacity 0.15s; }
.scp-refresh-btn:hover { opacity: 0.88; }

.scp-stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-bottom: 16px; }

.scp-stat-card { background: var(--fg-color); border-radius: 12px; padding: 20px; display: flex; align-items: flex-start; gap: 16px; border: 1px solid var(--border-color); overflow: hidden; }

.scp-stat-icon { width: 44px; height: 44px; border-radius: 10px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.scp-entries .scp-stat-icon { background: rgba(16,185,129,0.1); color: #10b981; }
.scp-scouts  .scp-stat-icon { background: rgba(59,130,246,0.1); color: #3b82f6; }
.scp-beds    .scp-stat-icon { background: rgba(20,184,166,0.1); color: #14b8a6; }
.scp-ghs     .scp-stat-icon { background: rgba(139,92,246,0.1); color: #8b5cf6; }

.scp-stat-label { font-size: 0.8rem; color: var(--text-muted); margin-bottom: 4px; font-weight: 500; }
.scp-stat-value { font-size: 1.75rem; font-weight: 700; color: var(--text-color); line-height: 1.2; }
.scp-stat-unit  { font-size: 0.7rem; color: var(--text-muted); text-transform: uppercase; margin-top: 2px; letter-spacing: 0.5px; }

.scp-stat-card.loading .scp-stat-value { animation: scp-pulse 1.4s ease-in-out infinite; }
@keyframes scp-pulse { 0%,100%{opacity:1} 50%{opacity:0.35} }

.scp-insights-bar { display: flex; gap: 20px; flex-wrap: wrap; padding: 12px 16px; background: var(--fg-color); border: 1px solid var(--border-color); border-radius: 10px; font-size: 0.8125rem; min-height: 42px; align-items: center; }
.scp-insight-item { display: flex; align-items: center; gap: 7px; }
.scp-insight-dot { width: 8px; height: 8px; border-radius: 50%; flex-shrink: 0; }
.scp-insight-label { color: var(--text-muted); }
.scp-insight-value { font-weight: 600; color: var(--text-color); }

.scp-nav-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 12px; }
.scp-nav-card { display: flex; align-items: center; gap: 14px; padding: 16px; background: var(--fg-color); border: 1px solid var(--border-color); border-radius: 12px; text-decoration: none; color: var(--text-color); transition: border-color 0.2s, box-shadow 0.2s; }
.scp-nav-card:hover { border-color: var(--primary); box-shadow: 0 4px 16px rgba(44,123,229,0.12); color: var(--text-color); text-decoration: none; }
.scp-nav-icon { width: 44px; height: 44px; border-radius: 10px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.scp-nav-scouts  { background: rgba(59,130,246,0.1); color: #3b82f6; }
.scp-nav-obs     { background: rgba(16,185,129,0.1); color: #10b981; }
.scp-nav-heat    { background: rgba(239,68,68,0.1);  color: #ef4444; }
.scp-nav-traps   { background: rgba(245,158,11,0.1); color: #f59e0b; }
.scp-nav-floor   { background: rgba(139,92,246,0.1); color: #8b5cf6; }
.scp-nav-reports { background: rgba(20,184,166,0.1); color: #14b8a6; }
.scp-nav-title { font-size: 0.9375rem; font-weight: 600; margin-bottom: 2px; }
.scp-nav-desc  { font-size: 0.8125rem; color: var(--text-muted); }
.scp-nav-body  { flex: 1; }
.scp-nav-arrow { opacity: 0.3; transition: opacity 0.2s, transform 0.2s; }
.scp-nav-card:hover .scp-nav-arrow { opacity: 0.7; transform: translateX(3px); }

@media (max-width: 768px) {
  .scp-stats-grid { grid-template-columns: repeat(2, 1fr); }
  .scp-nav-grid { grid-template-columns: 1fr; }
  .scp-header { flex-direction: column; }
}

script:
(function() {
  // Role-gate the tiles: a tile with data-roles="" shows for everyone; otherwise
  // it shows only if the user holds one of the listed roles. System Manager /
  // Administrator always see everything.
  var roles = (window.frappe && frappe.user_roles) || [];
  var isAdmin = roles.indexOf('System Manager') >= 0
    || roles.indexOf('Administrator') >= 0
    || (window.frappe && frappe.user && frappe.user.name === 'Administrator');
  root_element.querySelectorAll('.scpn-tile').forEach(function(tile) {
    var req = (tile.getAttribute('data-roles') || '')
      .split(',').map(function(s){return s.trim();}).filter(Boolean);
    if (req.length === 0) return; // everyone
    var ok = isAdmin || req.some(function(r){ return roles.indexOf(r) >= 0; });
    if (!ok) tile.classList.add('scpn-hide');
  });
})();

(function() {
  var COLORS = ['#ef4444','#3b82f6','#10b981','#f59e0b','#8b5cf6','#06b6d4','#f43f5e','#22c55e','#a78bfa','#fb923c'];
  var uid = 'sm_' + Date.now();
  var mapEl = root_element.querySelector('.scpmap-mapel');
  if (mapEl) mapEl.id = uid;
  var lmap = null, zoneLayer = null, scoutLayer = null;
  var center = [-0.3, 36.9], zoom = 15, aborter = null;
  var empNames = {};
  var dateInput = root_element.querySelector('.scpmap-dateinput');
  var today = new Date().toISOString().slice(0, 10);
  if (dateInput) dateInput.value = today;

  function qs(sel) { return root_element.querySelector(sel); }
  function showLoad() { var o=qs('.scpmap-overlay'),e=qs('.scpmap-empty'); if(o)o.style.display='flex'; if(e)e.style.display='none'; }
  function hideLoad(empty) { var o=qs('.scpmap-overlay'),e=qs('.scpmap-empty'); if(o)o.style.display='none'; if(e)e.style.display=empty?'flex':'none'; }
  function kpi(cls, val) { var el=qs('.'+cls); if(el)el.textContent=val; }
  function resetKpis() { kpi('scpmap-k-scouts',0); kpi('scpmap-k-beds',0); kpi('scpmap-k-zones',0); kpi('scpmap-k-mpb','0.0'); }
  function nameOf(id) { return empNames[id] || id || 'Unknown'; }

  function loadLeaflet(cb) {
    if (window.L) { cb(); return; }
    // Use Frappe's locally-bundled Leaflet (1.2.0) — no external CDN, so the
    // map can't hang forever when unpkg is slow/blocked.
    if (!document.querySelector('link[href*=leaflet]')) {
      var l=document.createElement('link'); l.rel='stylesheet'; l.href='/assets/frappe/js/lib/leaflet/leaflet.css'; document.head.appendChild(l);
    }
    var s=document.createElement('script'); s.src='/assets/frappe/js/lib/leaflet/leaflet.js';
    s.onload=cb;
    s.onerror=function(){ hideLoad(true); var e=qs('.scpmap-empty'); if(e) e.textContent='Map library failed to load'; };
    document.head.appendChild(s);
  }

  function initMap() {
    if (lmap) { lmap.remove(); lmap=null; }
    lmap = L.map(uid, { center:center, zoom:zoom, zoomControl:true, attributionControl:false });
    L.tileLayer('https://mt{s}.google.com/vt/lyrs=s&x={x}&y={y}&z={z}', { subdomains:['0','1','2','3'], maxZoom:21 }).addTo(lmap);
    zoneLayer = L.layerGroup().addTo(lmap);
    scoutLayer = L.layerGroup().addTo(lmap);
  }

  function render(data) {
    if (!lmap) return;
    zoneLayer.clearLayers(); scoutLayer.clearLayers();
    var zones=data.all_zones_geojson||[], entries=data.scouting_entries||[], summary=data.scouting_summary||{};
    var bounds=[];
    zones.forEach(function(z) {
      try {
        var gj=typeof z.raw_geojson==='string'?JSON.parse(z.raw_geojson):z.raw_geojson;
        var lyr=L.geoJSON(gj,{style:{color:'#22d3ee',weight:1.5,opacity:.45,fillOpacity:0},renderer:L.canvas()}).addTo(zoneLayer);
        try { var b=lyr.getBounds(); if(b.isValid())bounds.push([b.getSouth(),b.getWest()],[b.getNorth(),b.getEast()]); }catch(ex){}
      }catch(ex){}
    });
    var groups={};
    entries.forEach(function(e){var n=nameOf(e.scouts_name);if(!groups[n])groups[n]=[];groups[n].push(e);});
    var names=Object.keys(groups);
    var legend=qs('.scpmap-legend');
    names.forEach(function(name,i) {
      var color=COLORS[i%COLORS.length];
      var pts=groups[name].filter(function(e){return e.latitude&&e.longitude;}).map(function(e){return[+e.latitude,+e.longitude];});
      if(pts.length>1) L.polyline(pts,{color:color,weight:3,opacity:.85}).addTo(scoutLayer);
      if(pts.length>0){
        var last=pts[pts.length-1]; bounds.push(last);
        L.circleMarker(last,{radius:8,color:'#fff',fillColor:color,fillOpacity:1,weight:2}).bindTooltip(name,{permanent:false,direction:'top',offset:[0,-6]}).addTo(scoutLayer);
        L.circleMarker(last,{radius:15,color:color,fillOpacity:0,weight:1.5,opacity:.35}).addTo(scoutLayer);
      }
    });
    if (legend) {
      legend.innerHTML='';
      if(names.length>0) {
        legend.style.display='flex';
        names.forEach(function(n,i){
          var item=document.createElement('div'); item.className='scpmap-legend-item';
          var dot=document.createElement('span'); dot.className='scpmap-legend-dot'; dot.style.background=COLORS[i%COLORS.length];
          item.appendChild(dot); item.appendChild(document.createTextNode(' '+n)); legend.appendChild(item);
        });
      } else { legend.style.display='none'; }
    }
    if(bounds.length>0){try{lmap.fitBounds(bounds,{padding:[30,30],maxZoom:19});}catch(ex){}}
    kpi('scpmap-k-scouts', summary.total_unique_scouts!=null?summary.total_unique_scouts:names.length);
    kpi('scpmap-k-beds', summary.total_beds_covered||0);
    kpi('scpmap-k-zones', zones.length);
    kpi('scpmap-k-mpb', summary.average_minutes_per_bed?(+summary.average_minutes_per_bed).toFixed(1):'0.0');
  }

  function fetchAnalysis(dt) {
    if(aborter)aborter.abort();
    aborter=new AbortController();
    return fetch('/api/method/upande_scp.serverscripts.get_scouting_analysis.getScoutingAnalysis',{
      method:'POST',
      headers:{'Content-Type':'application/json','X-Frappe-CSRF-Token':(window.frappe&&frappe.csrf_token)||''},
      body:JSON.stringify({date:dt}),
      signal:aborter.signal
    }).then(function(r){return r.json();}).then(function(r){return r.message||{};});
  }

  // Most recent date that actually has a GPS-tagged scouting entry — used so the
  // map never sits blank on a quiet 'today' (or on a frozen/restored site).
  function latestScoutDate() {
    return frappe.call({
      method:'frappe.client.get_list',
      args:{doctype:'Scouting Entry', filters:[['latitude','is','set']], fields:['date_of_capture'], order_by:'date_of_capture desc', limit_page_length:1}
    }).then(function(r){var rows=(r&&r.message)||[]; return rows.length?rows[0].date_of_capture:null;}).catch(function(){return null;});
  }

  // Resolve scout payroll ids (e.g. MFK-00141) to real employee names.
  function resolveNames(entries) {
    var ids=[], seen={};
    entries.forEach(function(e){var id=e.scouts_name; if(id&&!seen[id]&&!(id in empNames)){seen[id]=1;ids.push(id);} });
    if(!ids.length) return Promise.resolve();
    return frappe.call({
      method:'frappe.client.get_list',
      args:{doctype:'Employee', filters:[['name','in',ids]], fields:['name','employee_name'], limit_page_length:0}
    }).then(function(r){ ((r&&r.message)||[]).forEach(function(e){ if(e.employee_name) empNames[e.name]=e.employee_name; }); }).catch(function(){});
  }

  // Wipe scout tracks/zones/legend so an empty date shows a clean map behind
  // the "no data" badge instead of the previous date's stale tracks.
  function clearMap() {
    if (scoutLayer) scoutLayer.clearLayers();
    if (zoneLayer) zoneLayer.clearLayers();
    var lg=qs('.scpmap-legend'); if(lg){ lg.innerHTML=''; lg.style.display='none'; }
  }

  function load(dt, allowFallback) {
    showLoad();
    fetchAnalysis(dt).then(function(d){
      var entries=d.scouting_entries||[];
      if(!entries.length && allowFallback){
        return latestScoutDate().then(function(ld){
          if(ld && ld!==dt){ if(dateInput)dateInput.value=ld; return load(ld,false); }
          clearMap(); hideLoad(true); resetKpis();
        });
      }
      if(!entries.length){ clearMap(); hideLoad(true); resetKpis(); return; }
      return resolveNames(entries).then(function(){ hideLoad(false); render(d); });
    }).catch(function(e){ if(e.name!=='AbortError'){ hideLoad(true); resetKpis(); } });
  }

  if(dateInput) dateInput.addEventListener('change',function(){load(this.value,false);});

  function boot(){loadLeaflet(function(){initMap();load(today,true);});}

  fetch('/api/resource/Map%20Settings/Map%20Settings',{headers:{'X-Frappe-CSRF-Token':(window.frappe&&frappe.csrf_token)||''}})
    .then(function(r){return r.json();})
    .then(function(r){var d=r.data||{};if(d.lat&&d.lon){center=[+d.lat,+d.lon];zoom=+d.default_zoom||15;}boot();})
    .catch(function(){boot();});
})();

style:
.scpmap{font-family:var(--font-stack);background:var(--fg-color);border:1px solid var(--border-color);border-radius:14px;overflow:hidden}
.scpmap-header{display:flex;align-items:center;justify-content:space-between;padding:14px 18px 10px;gap:10px}
.scpmap-hd-left{display:flex;align-items:center;gap:10px}
.scpmap-live-dot{width:9px;height:9px;border-radius:50%;background:#10b981;flex-shrink:0;animation:scpmap-livepulse 2s ease-in-out infinite}
@keyframes scpmap-livepulse{0%,100%{box-shadow:0 0 0 0 rgba(16,185,129,.4)}50%{box-shadow:0 0 0 6px rgba(16,185,129,0)}}
.scpmap-title{font-size:.9375rem;font-weight:600;color:var(--text-color);margin:0}
.scpmap-hd-right{display:flex;align-items:center;gap:8px}
.scpmap-dateinput{padding:6px 10px;border:1px solid var(--border-color);border-radius:8px;font-size:.8125rem;background:var(--bg-color);color:var(--text-color);outline:none}
.scpmap-dateinput:focus{border-color:var(--primary)}
.scpmap-fullbtn{display:inline-flex;align-items:center;gap:6px;padding:7px 13px;background:var(--primary);color:#fff;border-radius:8px;font-size:.8rem;font-weight:500;text-decoration:none;transition:opacity .15s}
.scpmap-fullbtn:hover{opacity:.85;color:#fff;text-decoration:none}
.scpmap-wrap{position:relative;height:460px;background:#0f172a}
.scpmap-mapel{width:100%;height:100%}
.scpmap-overlay{position:absolute;top:0;left:0;right:0;bottom:0;z-index:1000;background:rgba(15,23,42,.66);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:#e5e7eb;font-size:.875rem;backdrop-filter:blur(1px)}
.scpmap-empty{display:none;position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);z-index:1000;background:rgba(15,23,42,.86);color:#e5e7eb;padding:18px 26px;border-radius:12px;flex-direction:column;align-items:center;gap:10px;font-size:.85rem;box-shadow:0 10px 30px rgba(0,0,0,.4);text-align:center}
.scpmap-spinner{width:30px;height:30px;border:3px solid var(--border-color);border-top-color:var(--primary);border-radius:50%;animation:scpmap-spin .75s linear infinite}
@keyframes scpmap-spin{to{transform:rotate(360deg)}}
.scpmap-legend{position:absolute;bottom:12px;right:12px;z-index:900;background:rgba(0,0,0,.7);color:#fff;border-radius:10px;padding:9px 13px;display:none;flex-direction:column;gap:6px;font-size:.76rem;max-height:200px;overflow-y:auto;backdrop-filter:blur(6px)}
.scpmap-legend-item{display:flex;align-items:center;gap:7px;white-space:nowrap}
.scpmap-legend-dot{width:9px;height:9px;border-radius:50%;flex-shrink:0}
.scpmap-kpi-row{display:flex;align-items:center;padding:12px 18px;border-top:1px solid var(--border-color)}
.scpmap-kpi{display:flex;align-items:center;gap:10px;flex:1}
.scpmap-kpi-sep{width:1px;height:32px;background:var(--border-color);flex-shrink:0}
.scpmap-kpi-icon{width:32px;height:32px;border-radius:8px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.scpmap-icon-scouts{background:rgba(59,130,246,.1);color:#3b82f6}
.scpmap-icon-beds{background:rgba(20,184,166,.1);color:#14b8a6}
.scpmap-icon-zones{background:rgba(16,185,129,.1);color:#10b981}
.scpmap-icon-mpb{background:rgba(245,158,11,.1);color:#f59e0b}
.scpmap-kpi-val{font-size:1.3rem;font-weight:700;color:var(--text-color);line-height:1.2}
.scpmap-kpi-label{font-size:.72rem;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;margin-top:1px}
@media(max-width:768px){.scpmap-wrap{height:300px}.scpmap-kpi-row{flex-wrap:wrap;gap:10px}.scpmap-kpi-sep{display:none}.scpmap-kpi{flex:0 0 calc(50% - 5px)}}
